def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    my_c = 0
    my_d = 0
    op_c = 0
    op_d = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
        if b == 'C':
            op_c += 1
        else:
            op_d += 1

    last_me = me[-1]
    last_op = op[-1]
    rounds_left = 100 - n

    # Near the end, exploit pure cooperators and avoid pointless cooperation
    # against defectors. The last few rounds always favor defection if the
    # opponent has shown enough cooperation to be exploited.
    if rounds_left <= 1:
        return 'D'
    if op_d == 0:
        # Opponent has never defected. Against such a cooperator, defecting in
        # the final stretch is worth more than mutual cooperation.
        if rounds_left <= 12:
            return 'D'
        if n >= 20 and rounds_left <= 30 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Against a heavily defecting opponent, minimize losses and only rarely
    # probe cooperation. Long runs of aggression mean defection is safest.
    if op_d >= 80 and op_c <= 20:
        if n >= 60 and rounds_left <= 15:
            return 'D'
        if last_op == 'C' and op_c >= 2 and rng.random() < 0.18:
            return 'C'
        return 'D'

    # Estimate recent behavior over a sliding window. Short windows catch
    # sudden changes, longer windows give stable classification.
    w10 = min(10, n)
    w6 = min(6, n)
    op_recent_c10 = 0
    op_recent_c6 = 0
    me_recent_d6 = 0
    for i in range(n - w10, n):
        if history[i][1] == 'C':
            op_recent_c10 += 1
    for i in range(n - w6, n):
        if history[i][1] == 'C':
            op_recent_c6 += 1
        if history[i][0] == 'D':
            me_recent_d6 += 1

    # Detect a mostly cooperative opponent and lock in cooperation, with
    # occasional late exploitation.
    if op_recent_c10 >= 9:
        if rounds_left <= 10 and op_d <= 2:
            return 'D'
        if rng.random() < 0.04:
            return 'D'
        return 'C'

    # Detect a mostly defective recent run and defend.
    if op_recent_c6 <= 1 and op_d * 2 > n:
        if last_op == 'C' and op_c >= 2 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # If the opponent just defected, retaliate to deter exploitation. But if
    # we have been defecting almost continuously while the opponent mostly
    # cooperated, stop punishing and reset to cooperation.
    if last_op == 'D':
        if me_recent_d6 >= 5 and op_recent_c10 >= 8:
            return 'C'
        if op_d * 4 < n and rng.random() < 0.35:
            return 'C'
        if last_me == 'D' and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent last cooperated. Continue cooperation, but occasionally test
    # and exploit weak reciprocators. Exploit more as the match approaches
    # its end and retaliation becomes less costly.
    if n >= 2:
        # If opponent cooperated after our defection, exploit again with
        # moderate probability, since they appear forgiving.
        if last_me == 'D' and last_op == 'C':
            if rounds_left <= 20:
                return 'D'
            if rng.random() < 0.55:
                return 'D'
            return 'C'

    # Endgame: if the opponent has some defections but also considerable
    # cooperation, defect more often in the final rounds to grab payoff.
    if rounds_left <= 8:
        if op_d * 3 < n:
            return 'D'
        if rounds_left <= 3:
            return 'D'
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # Mid-game probing against sufficiently cooperative opponents.
    if op_recent_c10 >= 7:
        if rng.random() < 0.035:
            return 'D'
        return 'C'

    # If opponent is mixed and has defected more than cooperated overall,
    # lean toward defection.
    if op_d > op_c and op_d > 2:
        if last_op == 'C' and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Default: cooperate to build mutual cooperation, with rare probing.
    if rng.random() < 0.02:
        return 'D'
    return 'C'
